import { chromium } from "playwright";
import { readFile } from "node:fs/promises";
const metabolismJson = await readFile("C:/git/semio/semio/assets/semio/metabolism.kit.semio.json", "utf8");
const metabolismKit = JSON.parse(metabolismJson);
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
page.on("console", (msg) => console.log("[console]", msg.type(), msg.text()));
page.on("pageerror", (err) => console.log("[pageerror]", err.stack || err.message));
try {
  await page.goto("http://127.0.0.1:4182/", { waitUntil: "networkidle" });
  await page.evaluate(async (kit) => {
    const store = window.__SEMIO_STORE__;
    if (!store) throw new Error("no store");
    await store.execute("semio.sketchpad.createKit", "debug.kit", kit, false, false);
  }, metabolismKit);
  await page.waitForTimeout(1500);
  const kitId = await page.evaluate(() => {
    const store = window.__SEMIO_STORE__;
    const match = (store?.kitShallows?.() ?? []).find((kit) => String(kit?.name ?? "").toLowerCase().includes("metabolism"));
    return match?.id ?? null;
  });
  console.log("KIT_ID", kitId);
  await page.goto(`http://127.0.0.1:4182/kits/${kitId}`, { waitUntil: "networkidle" });
  await page.waitForTimeout(2000);
  const info = await page.evaluate((targetKitId) => {
    const actor = window.__SEMIO_ACTOR__;
    const store = window.__SEMIO_STORE__;
    const snapshot = actor?.getSnapshot?.();
    return {
      url: location.href,
      hasTbody: !!document.querySelector("tbody"),
      tbodyCount: document.querySelectorAll("tbody").length,
      rowIds: Array.from(document.querySelectorAll("[data-row-id]")).map((el) => el.getAttribute("data-row-id")).slice(0, 20),
      hasDiagram: !!document.querySelector('[data-testid="kit-diagram"]'),
      loadingText: document.body.textContent?.includes("Loading kit") || false,
      failedText: document.body.textContent?.includes("Failed to load kit app") || false,
      bodyText: document.body.textContent?.slice(0, 1000),
      kitApp: snapshot?.context?.kitApps?.[targetKitId ?? ""] ?? null,
      hasKitAppStore: store?.hasKitApp?.({ kit: targetKitId }) ?? null,
    };
  }, kitId);
  console.log("KIT_INFO", JSON.stringify(info, null, 2));
} finally {
  await browser.close();
}
