$ErrorActionPreference = 'Stop'; Push-Location 'c:\git\semio'; $script = @'
import { chromium } from "playwright";
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
page.on("console", (msg) => console.log("[console]", msg.type(), msg.text()));
page.on("pageerror", (err) => console.log("[pageerror]", err.stack || err.message));
try {
  await page.goto("http://127.0.0.1:4182/", { waitUntil: "networkidle" });
  const exports = await page.evaluate(async () => {
    const mod = await import("/assets/semio-D1Fmdttk.js");
    return Object.keys(mod).filter((key) => /importKitArchive|kitToSqlite|getSqlJs/.test(key));
  });
  console.log('EXPORTS', JSON.stringify(exports));
  const kitId = await page.evaluate(async () => {
    const semio = await import('/assets/semio-D1Fmdttk.js');
    const response = await fetch('/assets/semio/metabolism.zip');
    const bytes = new Uint8Array(await response.arrayBuffer());
    const imported = await semio.importKitArchive(bytes);
    const store = window.__SEMIO_STORE__;
    await store.execute('semio.sketchpad.createKit', 'debug.kit', imported.kit, false, false);
    const match = (store?.kitShallows?.() ?? []).find((kit) => String(kit?.name ?? '').toLowerCase().includes('metabolism'));
    return match?.id ?? null;
  });
  console.log('KIT_ID', kitId);
  await page.goto(`http://127.0.0.1:4182/kits/${kitId}`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(2000);
  const info = await page.evaluate((targetKitId) => {
    const actor = window.__SEMIO_ACTOR__;
    const store = window.__SEMIO_STORE__;
    const snapshot = actor?.getSnapshot?.();
    return {
