      kitApp: snapshot?.context?.kitApps?.[targetKitId ?? ''] ?? null,
      hasKitAppStore: store?.hasKitApp?.({ kit: targetKitId }) ?? null,
    };
  }, kitId);
  console.log('KIT_INFO', JSON.stringify(info, null, 2));
} finally {
  await browser.close();
}
