$ErrorActionPreference = 'Stop'; Push-Location 'c:\git\semio'; $script = @'
import { chromium } from "playwright";
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage();
page.on("console", (msg) => console.log("[console]", msg.type(), msg.text()));
page.on("pageerror", (err) => console.log("[pageerror]", err.stack || err.message));
try {
  await page.goto("http://127.0.0.1:4183/", { waitUntil: "networkidle" });
  const supported = await page.evaluate(() => {
    const store = window.__SEMIO_STORE__;
    return {
      available: store.availableKitKinds?.(),
      supported: store.supportedKitKinds?.(),
    };
  });
  console.log('KINDS', JSON.stringify(supported));
  const now = new Date().toISOString();
  const createResult = await page.evaluate(async (now) => {
    const store = window.__SEMIO_STORE__;
    const kit = { id: 'simple-kit', name: 'Simple Kit', createdAt: now, updatedAt: now, types: [{ id:'type-1', name:'Type 1', createdAt: now, updatedAt: now }], designs: [] };
    try {
      const result = await store.execute('semio.sketchpad.createKit', 'debug.kit', kit, false, false);
      return { ok: true, result };
    } catch (error) {
      return { ok: false, error: { message: error?.message, stack: error?.stack } };
    }
  }, now);
  console.log('CREATE', JSON.stringify(createResult, null, 2));
} finally {
  await browser.close();
}
